arabic_landing_v1.style.css:
*{box-sizing:border-box}
body{margin:0;font-family:sans-serif;background:#ffffff;color:#1a1a1a;line-height:1.7}
header,main,footer{padding:16px}
nav a{color:#0b4f8a;margin-inline-end:12px}
h1{font-size:1.8rem}
.grid{display:grid;gap:12px}
@media (min-width:600px){.grid{grid-template-columns:repeat(3,1fr)}}
button,a.cta-button{font:inherit;padding:8px 14px;border:2px solid #0b4f8a;background:#ffffff;color:#0b4f8a;border-radius:6px;cursor:pointer;text-decoration:none;display:inline-block}
button[aria-pressed=true],button[aria-selected=true]{background:#0b4f8a;color:#ffffff}
button:focus-visible,a:focus-visible,input:focus-visible,select:focus-visible{outline:3px solid #b35900;outline-offset:2px}
input,select{font:inherit;padding:6px;border:1px solid #555555;background:#ffffff;color:#1a1a1a}
table{border-collapse:collapse;width:100%}td,th{border:1px solid #cccccc;padding:6px;text-align:start}
[hidden]{display:none!important}
@media (prefers-reduced-motion: reduce){*{transition:none!important;animation:none!important}}

