arabic_dashboard_v1.script.js:
const search=document.getElementById('table-search'),filter=document.getElementById('status-filter');
function apply(){const term=search.value.trim().toLowerCase();let shown=0;
  document.querySelectorAll('#data-table tbody tr').forEach(r=>{const ok=(!term||r.textContent.toLowerCase().includes(term))&&(filter.value==='all'||r.dataset.status===filter.value);r.hidden=!ok;if(ok)shown++;});
  document.getElementById('row-count').textContent='عدد الصفوف الظاهرة: '+shown;document.getElementById('empty-state').hidden=shown!==0;}
search.addEventListener('input',apply);filter.addEventListener('change',apply);

