arabic_blog_v1.script.js:
let tag='all';const search=document.getElementById('post-search');
function apply(){const term=search.value.trim().toLowerCase();let shown=0;
  document.querySelectorAll('article.post-card').forEach(p=>{const ok=(tag==='all'||p.dataset.tags.split(/\s+/).includes(tag))&&(!term||p.textContent.toLowerCase().includes(term));p.hidden=!ok;if(ok)shown++;});
  document.getElementById('post-count').textContent='المقالات الظاهرة: '+shown;}
document.querySelectorAll('.tag-filter').forEach(b=>b.addEventListener('click',()=>{tag=b.dataset.tag;document.querySelectorAll('.tag-filter').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));apply();}));
search.addEventListener('input',apply);

